[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Biomedical Research Landscape 2024–2026</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        :root {
            --primary: #1a56db;
            --primary-dark: #1e40af;
            --secondary: #7e3af2;
            --success: #057a55;
            --warning: #c27803;
            --danger: #c81e1e;
            --gray-50: #f9fafb;
            --gray-100: #f3f4f6;
            --gray-200: #e5e7eb;
            --gray-300: #d1d5db;
            --gray-500: #6b7280;
            --gray-700: #374151;
            --gray-900: #111827;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
            line-height: 1.6;
            color: var(--gray-700);
            background: var(--gray-100);
        }

        .report-container {
            max-width: 1200px;
            margin: 0 auto;
            background: white;
        }

        .header {
            background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
            color: white;
            padding: 60px 40px;
        }

        .header h1 {
            font-size: 2.5rem;
            font-weight: 700;
            margin-bottom: 16px;
            line-height: 1.2;
        }

        .header .subtitle {
            font-size: 1.25rem;
            opacity: 0.9;
            max-width: 700px;
        }

        .header .meta {
            margin-top: 24px;
            font-size: 0.9rem;
            opacity: 0.8;
        }

        .executive-summary {
            background: var(--gray-50);
            border-left: 4px solid var(--primary);
            padding: 32px;
            margin: 40px;
            border-radius: 0 8px 8px 0;
        }

        .executive-summary h2 {
            color: var(--gray-900);
            font-size: 1.5rem;
            margin-bottom: 20px;
        }

        .kpi-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 16px;
            margin: 24px 0;
        }

        .kpi-card {
            background: white;
            border: 1px solid var(--gray-200);
            border-radius: 8px;
            padding: 20px;
            text-align: center;
        }

        .kpi-card .value {
            font-size: 2rem;
            font-weight: 700;
            color: var(--primary);
        }

        .kpi-card .label {
            font-size: 0.85rem;
            color: var(--gray-500);
            margin-top: 4px;
        }

        .takeaway-list {
            list-style: none;
            margin-top: 16px;
        }

        .takeaway-list li {
            padding: 12px 0;
            border-bottom: 1px solid var(--gray-200);
            display: flex;
            align-items: flex-start;
            gap: 12px;
        }

        .takeaway-list li:last-child {
            border-bottom: none;
        }

        .takeaway-icon {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            flex-shrink: 0;
            margin-top: 2px;
        }

        .takeaway-icon.strategic { background: #dbeafe; color: var(--primary); }
        .takeaway-icon.trend { background: #dcfce7; color: var(--success); }
        .takeaway-icon.policy { background: #fce7f3; color: #be185d; }

        .takeaway-content strong {
            color: var(--gray-900);
        }

        section {
            padding: 40px;
            border-bottom: 1px solid var(--gray-200);
        }

        section:last-child {
            border-bottom: none;
        }

        h2 {
            font-size: 1.75rem;
            color: var(--gray-900);
            margin-bottom: 8px;
        }

        .section-desc {
            color: var(--gray-500);
            margin-bottom: 32px;
            max-width: 800px;
        }

        .chart-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 24px;
        }

        .chart-card {
            background: var(--gray-50);
            border-radius: 12px;
            padding: 24px;
        }

        .chart-card h3 {
            font-size: 1rem;
            color: var(--gray-700);
            margin-bottom: 16px;
        }

        .chart-container {
            position: relative;
            height: 300px;
        }

        .data-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 24px;
            font-size: 0.9rem;
        }

        .data-table th {
            background: var(--primary);
            color: white;
            padding: 12px 16px;
            text-align: left;
            font-weight: 600;
        }

        .data-table td {
            padding: 12px 16px;
            border-bottom: 1px solid var(--gray-200);
        }

        .data-table tr:hover {
            background: var(--gray-50);
        }

        .badge {
            display: inline-block;
            padding: 4px 10px;
            border-radius: 12px;
            font-size: 0.75rem;
            font-weight: 600;
        }

        .badge-success { background: #dcfce7; color: #166534; }
        .badge-warning { background: #fef3c7; color: #92400e; }
        .badge-danger { background: #fee2e2; color: #991b1b; }
        .badge-primary { background: #dbeafe; color: #1e40af; }

        .insight-box {
            background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
            border-left: 4px solid var(--warning);
            padding: 20px;
            margin: 20px 0;
            border-radius: 0 8px 8px 0;
        }

        .insight-box strong {
            color: #92400e;
        }

        .footer {
            background: var(--gray-900);
            color: var(--gray-300);
            padding: 32px 40px;
            text-align: center;
            font-size: 0.85rem;
        }

        @media (max-width: 768px) {
            .header { padding: 40px 20px; }
            .header h1 { font-size: 1.75rem; }
